    ctx: &LoweringContext<'_, '_>,
    name: &str,
    param_ty: &PhpType,
) -> Option<(Op, PhpType)> {
    let local_ty = ctx.local_type(name).codegen_repr();
    match (param_ty.codegen_repr(), local_ty) {
        (PhpType::Array(param_elem), PhpType::Array(local_elem))
            if param_elem.codegen_repr() == PhpType::Mixed
                && local_elem.codegen_repr() != PhpType::Mixed =>
        {
            Some((
                Op::ArrayToMixed,
                PhpType::Array(Box::new(PhpType::Mixed)),
            ))
        }
        (
            PhpType::AssocArray {
                value: param_value, ..
            },
            PhpType::AssocArray {
                key: local_key,
                value: local_value,
            },
        ) if param_value.codegen_repr() == PhpType::Mixed
            && local_value.codegen_repr() != PhpType::Mixed =>
        {
            Some((
                Op::HashToMixed,
                PhpType::AssocArray {
                    key: local_key,
                    value: Box::new(PhpType::Mixed),
                },
            ))
        }
        _ => None,
    }
}"""
